// Logical preimages for data groups and reference-aware data/recipe operations.
using System;using System.Collections;using System.Collections.Generic;using System.Runtime.InteropServices;
namespace McgsInternalBridge {
 internal static class NativeDataLogicalCatalog {
  static string C(IntPtr p,int n){return NativeUsableEditPermit.ReadCurrentCString(p,n);}
  internal static List<object> StringVector(IntPtr p,int maximum){IntPtr b=NativeMemory.Ptr(p,0),e=NativeMemory.Ptr(p,4),c=NativeMemory.Ptr(p,8);long bytes=(long)NativeMemory.U(e)-NativeMemory.U(b),capacity=(long)NativeMemory.U(c)-NativeMemory.U(b);NativeMemory.Require(bytes>=0&&bytes%4==0&&capacity>=bytes&&capacity%4==0&&capacity<=(long)maximum*4&&((b==IntPtr.Zero)==(e==IntPtr.Zero&&c==IntPtr.Zero)),"Data CString vector header differs.");var r=new List<object>();for(int i=0;i<bytes/4;i++)r.Add(C(NativeMemory.Add(b,checked(i*4)),4096));NativeMemory.Require(NativeMemory.Ptr(p,0)==b&&NativeMemory.Ptr(p,4)==e&&NativeMemory.Ptr(p,8)==c,"Data CString vector changed during read.");return r;}
  internal static List<object> IntegerArray(NativeDataEngineering.Api a,IntPtr p){IntPtr vt=a.Engine.Address(0xCEAFA8);NativeMemory.Require(NativeMemory.Ptr(p,0)==vt,"Data cached member CArray table differs.");IntPtr b=NativeMemory.Ptr(p,4);int n=NativeMemory.I32(p,8),cap=NativeMemory.I32(p,12);NativeMemory.Require(n>=0&&cap>=n&&(n==0||b!=IntPtr.Zero),"Data cached member CArray header differs.");var r=new List<object>();for(int i=0;i<n;i++)r.Add(NativeMemory.I32(b,checked(i*4)));NativeMemory.Require(NativeMemory.Ptr(p,4)==b&&NativeMemory.I32(p,8)==n&&NativeMemory.I32(p,12)==cap,"Data cached member CArray changed during read.");return r;}
  internal static Dictionary<string,object> DataRecord(NativeDataEngineering.Api a,IntPtr p){a.Table(p,"CObjData");var words=new Dictionary<string,object>();foreach(int off in new[]{0x18,0x1C,0x20,0x24,0x28,0x2C,0x30,0x34,0x38,0x54,0x58,0x5C,0x60,0x64,0x68,0x6C,0x74,0x78,0x7C,0xA8,0xAC})words.Add("0x"+off.ToString("X"),unchecked((uint)NativeMemory.I32(p,off)));IntPtr bytes=NativeMemory.Add(p,0x40),buffer=NativeMemory.Ptr(bytes,4);int count=NativeMemory.I32(bytes,8),cap=NativeMemory.I32(bytes,12);NativeMemory.Require(count>=0&&cap>=count&&(count==0||buffer!=IntPtr.Zero),"Data byte-array header differs.");return new Dictionary<string,object>{{"object",NativeMemory.Hex(p)},{"native_id",NativeMemory.I32(p,0xA4)},{"name",C(NativeMemory.Add(p,8),256)},{"native_type",NativeMemory.I32(p,0x14)},{"comment",C(NativeMemory.Add(p,0xC),4096)},{"metadata_text",C(NativeMemory.Add(p,0x10),4096)},{"string3C",C(NativeMemory.Add(p,0x3C),4096)},{"initial_text",C(NativeMemory.Add(p,0x70),131072)},{"stringA0",C(NativeMemory.Add(p,0xA0),4096)},{"word_fields",words},{"byte_array40_hex",BitConverter.ToString((count==0?new byte[0]:NativeMemory.Bytes(buffer,count))).Replace("-","").ToLowerInvariant()},{"extension",NativeMemory.Hex(NativeMemory.Ptr(p,0xB0))},{"alarm_known_values",NativeAlarmRawCapture.KnownValues(a,p)},{"cached_member_ids",IntegerArray(a,NativeMemory.Add(p,0x80))},{"related_group_names",StringVector(NativeMemory.Add(p,0x94),50000)},{"member_names",StringVector(NativeMemory.Add(p,0xB4),50000)}};}
  // Keep the existing editable scalar aliases single-sourced, without duplicate expected values.
  internal static Dictionary<string,object> DataEditableRecord(NativeDataEngineering.Api a,IntPtr p){var r=DataRecord(a,p);var words=(Dictionary<string,object>)r["word_fields"];r["range0_bits"]=words["0x74"];r["range1_bits"]=words["0x78"];r["flags"]=words["0x7C"];words.Remove("0x74");words.Remove("0x78");words.Remove("0x7C");return r;}
  internal static List<Dictionary<string,object>> Data(NativeDataEngineering.Api a){var r=new List<Dictionary<string,object>>();foreach(IntPtr p in a.DataObjects())r.Add(DataRecord(a,p));return r;}
  internal static Dictionary<string,object> RecipeRecord(NativeDataEngineering.Api a,IntPtr p){a.Table(p,"CRecipe");var definitions=new List<object>();var columns=a.Columns(p);foreach(IntPtr col in columns)definitions.Add(new Dictionary<string,object>{{"variable_name",C(NativeMemory.Add(col,8),4096)},{"caption",C(NativeMemory.Add(col,12),4096)},{"native_kind",NativeMemory.I32(col,16)}});var rows=new List<object>();foreach(IntPtr row in a.CellRows(p,columns.Count)){var cells=new List<object>();for(int j=0;j<columns.Count;j++)cells.Add(C(NativeMemory.Add(NativeMemory.Ptr(row,4),4*j),131072));rows.Add(cells);}return new Dictionary<string,object>{{"object",NativeMemory.Hex(p)},{"name",C(NativeMemory.Add(p,8),256)},{"format_bits",unchecked((uint)NativeMemory.I32(p,0x34))},{"raw_byte38",Marshal.ReadByte(p,0x38)},{"columns",definitions},{"rows",rows}};}
  internal static List<Dictionary<string,object>> Recipes(NativeDataEngineering.Api a){var r=new List<Dictionary<string,object>>();foreach(IntPtr p in a.Recipes())r.Add(RecipeRecord(a,p));return r;}
 }
